These were defined in \eqref{eq: total and tail mass processes} as
\begin{equation*}
	u_n \vcentcolon= \sum_{i = 1}^\infty q_n(i) \quad \text{and} \quad v_n(j) \vcentcolon= \sum_{i = j}^\infty q_n(i) \quad \text{for all} \quad j \geq 1,
\end{equation*}
respectively.

nodes.statement:
Our proof of Theorem \ref{the: main theorem exponential case} can be easily adapted to prove an analogous result for the basic learning scheme. Specifically, assume that the hypotheses of Theorem \ref{the: main theorem exponential case} hold, except that the basic learning scheme is used instead of the refined learning scheme, and let
\begin{equation*}
	\tilde{\sigma}_{\mathrm{eq}}(a, b, m, \Delta) \vcentcolon=
	\begin{cases}
		\frac{1}{\mu}\left[\log \left(\frac{\rho_{\min} - u(a)}{\rho_{\min} - m \Delta}\right)\right]^+ & \text{if} \quad u(a) < \rho_{\min}, \\
		0 & \text{if} \quad \rho_{\min} \leq u(a) \leq \rho_{\max}, \\
		\frac{1}{\mu}\left[\log \left(\frac{u(a) - \rho_{\max}}{(m + 1) \Delta - \rho_{\max}}\right)\right]^+ & \text{if} \quad u(a) > \rho_{\max}.
	\end{cases}
\end{equation*}
It follows from \eqref{eq: total number of tasks} that $m\Delta < u(t) < (m + 1)\Delta$ for all $a + \tilde{\sigma}_{\mathrm{eq}}(a, b, m, \Delta) < t \leq b$. The strong law of large numbers for the total number of tasks provided in Proposition \ref{prop: total number of tasks} implies that $u_n(t)$ converges uniformly over $[0, T]$ to $u(t)$ with probability one. Hence, \eqref{seq: main result 1} holds for all $\sigma > \tilde{\sigma}_{\mathrm{eq}}(a, b, m, \Delta)$ when the basic learning scheme is used. Corollary \ref{cor: decay of the tail} applies to the basic learning scheme with exactly the same proof; the only difference is that the quantity $\sigma_{\mathrm{bd}}(a, b, m, \Delta)$ in the statement must be replaced by $\tilde{\sigma}_{\mathrm{eq}}(a, b, m, \Delta)$. In particular, \eqref{seq: main result 3} also holds for the basic learning scheme if $\sigma > \tilde{\sigma}_{\mathrm{eq}}(a, b, m, \Delta)$. Finally, we prove that \eqref{seq: main result 2} holds for the basic learning scheme and all
\begin{equation*}
	\sigma > \tilde{\sigma}(a, b, m, \Delta) \vcentcolon= \tilde{\sigma}_{\mathrm{eq}}(a, b, m, \Delta) + \frac{1}{\mu}\log\left(\frac{\rho_{\min}}{\rho_{\min} - m \Delta}\right)
\end{equation*}
by arguing as in the proof of Theorem \ref{the: main theorem exponential case}. The only difference with the proof for the refined learning scheme is that all instances of $\sigma_{\mathrm{bd}}(a, b, m, \Delta)$ must be replaced by $\tilde{\sigma}_{\mathrm{eq}}(a, b, m, \Delta)$.

Specifically, consider the metric $d$ defined by
\begin{equation*}
	d(x, y) \vcentcolon= \sum_{i = 0}^\infty \frac{\min\left\{|x(i) - y(i)|, 1\right\}}{2^i} \quad \text{for all} \quad x, y \in \mathbbm{R}^{\mathbbm{N}},
\end{equation*}
which generates the product topology on $\mathbbm{R}^{\mathbbm{N}}$.

The topology of uniform convergence equipped to the space $D_{\mathbbm{R}^{\mathbbm{N}}}[0, T]$ is given by the following metric:
\begin{equation*}
	\varrho(x, y) \vcentcolon= \sup_{t \in [0, T]} d\left(x(t), y(t)\right) \quad \text{for all} \quad x, y \in D_{\mathbbm{R}^{\mathbbm{N}}}[0, T].
\end{equation*}

The sample paths of the occupancy states and thresholds are defined as deterministic functions of the following stochastic primitives.

\begin{itemize}
	\item \textit{Driving Poisson processes:} a family $\set{\mathcal{N}_i}{i \geq 0}$ of independent Poisson processes of unit rate, defined on a common probability space $(\Omega_D, \mathcal{F}_D, \mathbbm{P}_D)$.

	\item \textit{Selection variables:} a sequence $\set{U_j}{j \geq 1}$ of independent and identically distributed uniform random variables with values on $[0, 1)$,  defined on a common probability space $(\Omega_S, \mathcal{F}_S, \mathbbm{P}_S)$.

	\item \textit{Initial conditions:} families $\set{q_n(0)}{n \geq 1}$ and $\set{\ell_n(0)}{n \geq 1}$ of random variables describing the initial conditions of the systems, defined on the common probability space $(\Omega_I, \mathcal{F}_I, \mathbbm{P}_I)$ and satisfying the assumptions introduced in Section \ref{sec: notation and assumptions}.
\end{itemize}

For each occupancy state $q \in Q$, we define the intervals
\begin{equation*}
	I_i(q) \vcentcolon= \left[1 - q(i - 1), 1 - q(i)\right) \quad \text{for all} \quad i \geq 1.
\end{equation*}

If $q(j) < 1$ for some $j \in \mathbbm{N}$, then we also define
\begin{equation*}
	J_i(q, j) \vcentcolon= \left[\frac{1 - q(i - 1)}{1 - q(j)}, \frac{1 - q(i)}{1 - q(j)}\right) \quad \text{for all} \quad 1 \leq i \leq j.
\end{equation*}
These intervals yield another partition of $[0, 1)$. In this case, the length of $J_i(q, j)$ is the fraction of server pools having exactly $i - 1$ tasks, but only among those server pools with at most $j - 1$ tasks; we define $J_i(q, j) \vcentcolon= \emptyset$ for all $1 \leq i \leq j$ when $q(j) = 1$.

We define
\begin{equation*}
	r_{ij}(q, \ell) \vcentcolon= \begin{cases}
		\ind{U_j \in J_i(q, \ell)} & \text{if} \quad i - 1 < \ell, \\
		\ind{q(\ell) = 1, U_j \in J_i(q, h)} & \text{if} \quad \ell \leq i - 1 < h, \\
		\ind{q(h) = 1, U_j \in I_i(q)} & \text{if} \quad i - 1 \geq h,
	\end{cases}
	\quad \text{for all} \quad i,j \geq 1.
\end{equation*}

We postulate that
\begin{equation*}
	\mathcal{N}_n^\lambda(t) \vcentcolon= \mathcal{N}_0\left(n\int_0^t \lambda(s)ds\right)
\end{equation*}
is the number of tasks that arrive to the system with $n$ server pools during the interval $[0, t]$, we denote the jump times of $\mathcal{N}_n^\lambda$ by $\set{\tau_{n,k}}{k \geq 1}$ and we let $\tau_{n,0} \vcentcolon= 0$.

For each $n$ and each pair of functions $\map{q}{[0, T]}{Q}$ and $\map{\ell}{[0, T]}{\mathbbm{N}}$, we introduce two infinite-dimensional counting processes, for arrivals and departures, denoted $\mathcal{A}_n(q, \ell)$ and $\mathcal{D}_n(q)$, respectively. The $i = 0$ coordinates of these two counting processes are identically zero, whereas the other coordinates are defined as follows:
\begin{equation*}
	\begin{split}
		&\mathcal{A}_n(q, \ell, t, i) \vcentcolon= \frac{1}{n} \sum_{j = 1}^{\mathcal{N}_n^\lambda(t)} r_{ij}\left(q\left(\tau_{n, j}^-\right), \ell\left(\tau_{n, j}^-\right)\right), \\
		&\mathcal{D}_n(q, t, i) \vcentcolon= \frac{1}{n} \mathcal{N}_i\left(n\int_0^t \mu i \left[q(s, i) - q(s, i + 1)\right]ds\right),
	\end{split}
	\quad \text{for all} \quad i \geq 1.
\end{equation*}

In addition, we define
\begin{equation*}
	\mathcal{A}_n \vcentcolon= \mathcal{A}_n(q_n, \ell_n), \quad \mathcal{D}_n \vcentcolon= \mathcal{D}_n(q_n) \quad \text{and} \quad h_n \vcentcolon= \ell_n + \Delta,
\end{equation*}
and we rewrite the implicit equations as follows:
\begin{subequations}
	\begin{align}
		&q_n(t) = q_n(0) + \mathcal{A}_n(t) - \mathcal{D}_n(t), \\
		&\ell_n(t) = \ell_n(0) + \sum_{k = 1}^{\mathcal{N}_n^\lambda(t)} \Delta \left[\ind{q_n\left(\tau_{n, k}^-, \ell_n\left(\tau_{n, k}^-\right)\right) = 1,\ nq_n\left(\tau_{n, k}^-, h_n\left(\tau_{n, k}^-\right)\right) \geq n - 1} - \ind{q_n\left(\tau_{n, k}^-, \ell_n\left(\tau_{n, k}^-\right)\right) \leq \alpha_n}\right]. \end{align}
\end{subequations}

First let us prove that there exists $k \in \mathbbm{N}$ such that $q_n(t, k \Delta + 1) = 0$ for all $t \in [0, T]$ and all sufficiently large $n$ with probability one. Note that the set
\begin{equation*}
	\bigcap_{m \geq 1} \bigcup_{n \geq m} \set{\omega \in \Omega}{q_n(\omega, t, k \Delta + 1) > 0\ \text{for some}\ t \in [0, T]}
\end{equation*}
is measurable for each $k \in \mathbbm{N}$ since the occupancy processes have right-continuous sample paths. We must establish that this set has probability zero for some $k$.

Consider the sets
\begin{equation*}
	E_n^k \vcentcolon= \set{\omega \in \Omega}{q_n(\omega, t, k \Delta + 1) > 0\ \text{for some}\ t \in [0, T]}.
\end{equation*}
By the Borel-Cantelli lemma, it is enough to prove that there exists $k \in \mathbbm{N}$ such that
\begin{equation} \sum_{n = 1}^\infty \mathbbm{P}\left(E_n^k\right) < \infty.
\end{equation}

Suppose that $k > B / \Delta$. This implies that $q_n(0, k\Delta + 1) = 0$ and $\ell_n(0) \leq (k - 1) \Delta$. Only the server pools with at most $h_n - 1 \leq k\Delta - 1$ tasks can receive incoming tasks while $\ell_n \leq (k - 1)\Delta$, and therefore $q_n(k\Delta + 1)$ remains zero until $\ell_n$ reaches $k\Delta$. In order to reach $k\Delta$, the threshold must reach $(k - 1)\Delta$ first, and then $nq_n(k\Delta)$ must grow from $n - 1$ to $n$ for $\ell_n$ to increase. Hence,
\begin{align*}
	\mathbbm{P}\left(E_n^k\right) &\leq \mathbbm{P}\left(nq_n(t, k\Delta) \geq n - 1 \ \text{for some} \ t \in [0, T]\right) \\
	&\leq \mathbbm{P}\left(nu_n(t) \geq k\Delta \left(n - 1\right) \ \text{for some} \ t \in [0, T]\right),
\end{align*}
where the last inequality follows from $u_n(t) / k\Delta \geq q_n(t, k\Delta)$; this holds since $q_n(t)$ is a non-increasing sequence.

Applying a Chernoff bound, we conclude that
\begin{align*}
	\mathbbm{P}\left(E_n^k\right) \leq \mathbbm{P}\left(\mathcal{N}_n^\lambda(T) \geq (k\Delta - B) n - k\Delta \right) \leq \frac{\mathrm{e}^{A\left(\mathrm{e} - 1\right)n}}{\mathrm{e}^{(k\Delta - B)n - k\Delta}}, \quad \text{with} \quad A \vcentcolon= \int_0^T \lambda(s)ds < \infty.
\end{align*}

It follows from (b) that $\mathcal{A}_k(t, i) = \mathcal{A}_k(t_0, i)$ for all $t \in [t_0, t_1]$ and all $i > j$, because tasks are only assigned to server pools with strictly fewer than $j$ tasks during $[t_0, t_1]$ in all the systems corresponding to the sequence $\mathcal{K}$. Thus, \eqref{seq: occupancy state} implies that
\begin{equation} q_k(t, i) = q_k(t_0, i) - \left[\mathcal{D}_k(t, i) - \mathcal{D}_k(t_0, i)\right] \quad \text{for all} \quad t \in [t_0, t_1] \quad \text{and all} \quad i > j.
\end{equation}

As indicated in Section \ref{app: relative compactness} of the appendix, convergence of a sequence of functions with respect to $\varrho$ implies uniform convergence over $[0, T]$ of the coordinate functions. Hence, (a) and \eqref{seq: fslln for departures 2} yield
\begin{equation} \lim_{k \to \infty} \sup_{t \in [0, T]} \left|\mathcal{D}_k(t, i) - \int_0^t \mu i \left[q(i, s) - q(i, s + 1)\right]ds\right| = 0 \quad \text{for all} \quad i \geq 0.
\end{equation}

By Proposition \ref{prop: definition of Omega_T}, there exists $B_T > 0$ such that $q_k(i)$ is identically zero for all $i > B_T$ and all large enough $k \in \mathcal{K}$; this implies, in particular, that $q(i)$ is identically zero as well for all $i > B_T$. Therefore, we conclude from (a), \eqref{eq: decomposition with no arrivals} and \eqref{eq: limit of departure processes} that
\begin{align*}
	\begin{array}{ll}
		\displaystyle q(t, i) = q(t_0, i) - \int_{t_0}^t \mu i\left[q(s, i) - q(s, i + 1)\right]ds & \quad \text{for} \quad j < i < B_T, \\ [3ex]
		\displaystyle q(t, i) = q(t_0, i) - \int_{t_0}^t \mu iq(s, i)ds & \quad \text{for} \quad i = B_T.
	\end{array}
\end{align*}

The convergence of $\set{v_k(j + 1)}{k \in \mathcal{K}}$ follows from (a) and the observation that $q_k(i)$ is identically zero for all $i > B_T$ and all large enough $k \in \mathcal{K}$. Moreover, $v(j + 1) = \sum_{i = j + 1}^{B_T} q(i)$, and in particular, $v(j + 1)$ is differentiable on $(t_0, t_1)$. It follows that
\begin{equation*}
	\dot{v}(t, j + 1) = \sum_{i = j + 1}^{B_T} -\mu i \left[q(t, i) - q(t, i + 1)\right] = -\mu v(t, j + 1) - \mu j q(t, j + 1) \quad \text{for all} \quad t \in (t_0, t_1).
\end{equation*}

Note that $q(j + 1)$ is a non-negative function, thus
\begin{equation*}
	v(t, j + 1) \leq v(t_0, j + 1) \mathrm{e}^{-\mu(t - t_0)} < u(t_0) \mathrm{e}^{-\mu(t - t_0)} \quad \text{for all} \quad t \in [t_0, t_1].
\end{equation*}
The last inequality is strict since $j \geq 1$.

It follows from \eqref{eq: total number of tasks} that the next inequality holds for all $t \in [a , b]$:
\begin{equation} \begin{split}
		u(t) &= u(a)\mathrm{e}^{-\mu(t - a)} + \int_a^t \rho(s) \mu \mathrm{e}^{-\mu(t - s)}ds \\
		&\leq u(a)\mathrm{e}^{-\mu(t - a)} + \int_a^t \rho_{\max} \mu \mathrm{e}^{-\mu(t - s)}ds = \rho_{\max} + \left[u(a) - \rho_{\max}\right]\mathrm{e}^{-\mu(t - a)}.
	\end{split}
\end{equation}

We fix an arbitrary $\omega \in \Omega_T$, which is omitted from the notation for brevity. By Definition~\ref{def: (Delta, m)-bounded}, we may consider positive constants $\delta$ and $\varepsilon$ such that
\begin{align*}
	\frac{\rho_{\max}}{(m + 1) \Delta} < 1 - \delta = \frac{\rho_{\max} + \varepsilon}{(m + 1) \Delta}.
\end{align*}
Note that $\varepsilon$ can be expressed in terms of $\delta$. In other words, if $\delta$ is given, then $\varepsilon$ is determined.

For each positive $\delta$, satisfying the previous inequality, and each $\theta \in (0, 1)$, we define
\begin{align*}
	\sigma(\delta, \theta) &\vcentcolon= \min \set{s \geq 0}{\left[u(a) - \rho_{\max}\right]\mathrm{e}^{-\mu s} \leq \theta \varepsilon} \\
	&= \begin{cases}
		\frac{1}{\mu}\left[\log\left(\frac{u(a) - \rho_{\max}}{\theta\left[(1 - \delta)(m + 1) \Delta - \rho_{\max}\right]}\right)\right]^+	&	\text{if} \quad u(a) > \rho_{\max}, \\
		0	&	\text{if} \quad u(a) \leq \rho_{\max}.
	\end{cases}
\end{align*}
Observe that $\sigma_{\mathrm{bd}}(a, b, m, \Delta)$ is the infimum of $\delta + \sigma(\delta, \theta)$. Therefore, we can choose $\delta$ and $\theta$ such that $\sigma > \delta + \sigma(\delta, \theta)$. Below we assume that $\delta$ and $\theta$ enforce the latter condition.

By Proposition \ref{prop: definition of Omega_T} and \eqref{ass: conditions on alpha}, there exists $n_0$ such that the following statements hold for all $n \geq n_0$.
\begin{enumerate}
	\item[(i)] $\ell_n(t) \leq B_T$ for all $t \in [0, T]$.

	\item[(ii)] $\mathcal{N}_n^\lambda$ has at least $B_T - m \Delta$ jumps on each subinterval of $[a, b]$ of length at least $\delta$; recall that the load is $\Delta$-bounded in $[a, b]$ and thus $\lambda$ is lower bounded by a positive constant in $[a, b]$.

	\item[(iii)] $1 - \delta < \alpha_n < 1 - 1 / n$.
\end{enumerate}

Furthermore, it follows from Proposition \ref{prop: total number of tasks} that there exists $n_{\mathrm{bd}} \geq n_0$ such that
\begin{equation*}
	\sup_{t \in [0, T]} \left|u_n(t) - u(t)\right| \leq (1 - \theta)\varepsilon \quad \text{for all} \quad t \in [0, T] \quad \text{and all} \quad n \geq n_{\mathrm{bd}}.
\end{equation*}

Suppose that $j \geq (m + 1) \Delta$ and $n \geq n_{\mathrm{bd}}$. If $t \in [a, b]$, then
\begin{align*}
	q_n(t, j) \leq \frac{1}{j} \sum_{i = 1}^j q_n(t, i) \leq \frac{u_n(t)}{j} &\leq \frac{u(t) + (1 - \theta)\varepsilon}{(m + 1) \Delta} \\ 
	&\leq \frac{\rho_{\max} + \left[u(a) - \rho_{\max}\right]\mathrm{e}^{-\mu(t - a)} + (1 - \theta)\varepsilon}{(m + 1) \Delta}.
\end{align*}
The first inequality follows from the fact that $q_n(t) \in Q$ is a non-increasing sequence, and the last inequality follows from \eqref{eq: upper bound for u}. If $t \in [a + \sigma(\delta, \theta), b]$, then $t - a \geq \sigma(\delta, \theta)$ and thus
\begin{align*}
	&q_n(t, j) \leq \frac{\rho_{\max} + \varepsilon}{(m + 1) \Delta} = 1 - \delta < \alpha_n < 1 - \frac{1}{n} \\
	&\text{for all} \quad j \geq (m + 1) \Delta, \quad t \in [a + \sigma(\delta, \theta), b], \quad n \geq n_{\mathrm{bd}}.
\end{align*}

We fix an arbitrary $\omega \in \Omega_T$. For brevity, $\omega$ is omitted from the notation and we set $r \vcentcolon= (m + 1) \Delta$. Suppose that the statement of the corollary does not hold. Then there exist $\varepsilon > 0$ and an increasing sequence of natural numbers $\mathcal{K}$ such that
\begin{align*}
	\sup_{t \in [a + \sigma, b]} v_k(t, r + 1)e^{\mu\left[t - (a + \sigma)\right]} > u(a + \sigma) + \varepsilon \quad \text{for all} \quad k \in \mathcal{K}.
\end{align*}

Note that $\ell_k(t) \leq m \Delta$ for all $t \in [a + \sigma, b]$ implies that $q_k(t, r) \leq 1 - 1 / k$ for all $t \in [a + \sigma, b]$. Indeed, no arrival can result in $q_k(r)$ going from $1 - 1 / k$ to $1$ because such an arrival would also result in the threshold increasing to $r = (m + 1) \Delta$. Consequently, Proposition \ref{prop: tail number of tasks} holds with $j = r$ along the interval $[a + \sigma, b]$, and in particular, there exists a function $v(r + 1)$ such that
\begin{align*}
	&v(t, r + 1) < u(a + \sigma)e^{-\mu\left[t - (a + \sigma)\right]} \quad \text{for all} \quad t \in [a + \sigma, b], \\
	&\lim_{k \to \infty} \sup_{t \in [a + \sigma, b]} \left|v_k(t, r + 1) - v(t, r + 1)\right| = 0.
\end{align*}
This leads to a contradiction, so the statement of the corollary must hold.

We omit $\omega$ from the notation for brevity. It follows from \eqref{seq: occupancy state} that
\begin{equation*}
	\sum_{i = 1}^j q_k(t, i) - \sum_{i = 1}^j q_k\left(\tau_{k, 1}, i\right) = \sum_{i = 1}^j \left[\mathcal{A}_k(t, i) - \mathcal{A}_k\left(\tau_{k, 1}, i\right)\right] - \sum_{i = 1}^j \left[\mathcal{D}_k(t, i) - \mathcal{D}_k\left(\tau_{k, 1}, i\right)\right].
\end{equation*}

Note that all tasks are assigned to server pools with at most $j - 1$ tasks during $(\tau_{k, 1}, t]$, so the first term on the right-hand side can be expressed as follows:
\begin{equation*}
	\sum_{i = 1}^j \left[\mathcal{A}_k(t, i) - \mathcal{A}_k\left(\tau_{k, 1}, i\right)\right] = \frac{1}{k}\left[\mathcal{N}_k^\lambda(t) - \mathcal{N}_k^\lambda\left(\tau_{k, 1}\right)\right].
\end{equation*}

Using the process $\delta_k(j)$ defined in \eqref{eq: error process}, we may write
\begin{align*}
	\sum_{i = 1}^j q_k(t, i) - \sum_{i = 1}^j q_k\left(\tau_{k, 1}, i\right) &= \int_{\tau_{k, 1}}^t \lambda(s)ds \\
	&- \sum_{i = 1}^j \int_{\tau_{k, 1}}^t \mu i \left[q_k(s, i) - q_k(s, i + 1)\right]ds + \delta_k(t, j) - \delta_k(\tau_{k, 1}, j) \\
	&\geq \int_{\tau_{k, 1}}^t \left[\lambda(s) - \mu j\right]ds - 2\sup_{s \in [0, T]} \left|\delta_k(s, j)\right|.
\end{align*}
The last inequality follows from the fact that
\begin{equation*}
	\sum_{i = 1}^j i\left[q_k(s, i) - q_k(s, i + 1)\right] = \sum_{i = 1}^j q_k(s, i) - jq_k(s, j + 1) \leq j \quad \text{if} \quad s \in [0, T] \quad \text{and} \quad k \in \mathcal{K}.
\end{equation*}
This completes the proof.

We omit $\omega$ from the notation for brevity, and we assume that $j > 0$ since otherwise the statement holds trivially. Fix $\gamma \in [0, 1/2)$ and consider the random times defined as
\begin{align*}
	&\xi_{k, 2} \vcentcolon= \inf \set{t \geq \zeta_{k, 1}}{q_k(t, j) \leq \max\{\alpha_k, 1 - k^{-\gamma}\}}, \\
	&\xi_{k, 1} \vcentcolon= \sup \set{t \leq \xi_{k, 2}}{q_k(t, j) = 1}.
\end{align*}

We conclude from \eqref{ass: conditions on alpha} and \eqref{eq: error process goes to zero} that
\begin{equation*}
	\lim_{k \to \infty} \frac{1}{1 - \alpha_k}\left[2\sup_{s \in [0, T]} |\delta_k(s, j)| + \frac{j}{k}\right] = \lim_{k \to \infty} \frac{1}{k^{\gamma_0}(1 - \alpha_k)}\left[2\sup_{s \in [0, T]} k^{\gamma_0}|\delta_k(s, j)| + \frac{j}{k^{1 - {\gamma_0}}}\right] = 0.
\end{equation*}
If $1 - \alpha_k$ is replaced by $k^{-\gamma}$ on the left-hand side, then the limit is also equal to zero by \eqref{eq: error process goes to zero}. Consequently, for all sufficiently large $k \in \mathcal{K}$, we have
\begin{equation*}
	\sum_{i = 1}^j q_k(t, i) - \sum_{i = 1}^j q_k\left(\tau_{k, 1}^-, i\right) \geq - 2\sup_{s \in [0, T]} \left|\delta_k(s, j)\right| - \frac{j}{k} > - \min\left\{1 - \alpha_k, k^{-\gamma}\right\}
\end{equation*}
for all $t \in \left[\tau_{k, 1}, \tau_{k, 2}\right]$. This implies \eqref{eq: statement to prove lemma} for all large enough $k \in \mathcal{K}$; note that \eqref{eq: statement to prove lemma} holds trivially when $\xi_{k, 1} > \zeta_{k, 2}$.

As in the proof of Proposition \ref{prop: bounded threshold}, it follows from \eqref{eq: total number of tasks} that the following inequality holds for all times $a \leq a + \sigma_0 \leq t \leq b$:
\begin{equation} \begin{split}
		u(t) &= u(a + \sigma_0)\mathrm{e}^{-\mu[t - (a + \sigma_0)]} + \int_{a + \sigma_0}^t \rho(s) \mu \mathrm{e}^{-\mu(t - s)}ds \\
		&\geq u(a + \sigma_0)\mathrm{e}^{-\mu[t - (a + \sigma_0)]} + \int_{a + \sigma_0}^t \rho_{\min} \mu \mathrm{e}^{-\mu(t - s)}ds \\
		&= \rho_{\min} + \left[u(a + \sigma_0) - \rho_{\min}\right]\mathrm{e}^{-\mu[t - (a + \sigma_0)]}.
	\end{split}
\end{equation}
In this equation, $\rho_{\min}$ is as in Definition \ref{def: (Delta, m)-bounded}.

Fix $\sigma(a, b, m, \Delta) < \sigma < b - a$ as in the statement of the theorem, and for each $0 < \varepsilon < \rho_{\min} - m\Delta$ let
\begin{equation*}
	\sigma(\varepsilon) \vcentcolon= \min \set{s \geq 0}{\rho_{\min}\left(1 - e^{-\mu s}\right) - \varepsilon \geq m\Delta} = \frac{1}{\mu}\log \left(\frac{\rho_{\min}}{\rho_{\min} - m\Delta - \varepsilon}\right).
\end{equation*}
Recall the definitions of $\sigma(a, b, m, \Delta)$ and $\sigma_{bd}(a, b, m, \Delta)$ provided in Definition \ref{def: (Delta, m)-bounded} and Proposition~\ref{prop: bounded threshold}, respectively. We fix $\sigma_0 > \sigma_{\mathrm{bd}}(a, b, m, \Delta)$ and $\varepsilon > 0$ such that $\sigma = \sigma_0 + \sigma(\varepsilon) + \varepsilon$. This is possible since $\sigma_{\mathrm{bd}}(a, b, m, \Delta) + \sigma(\varepsilon) + \varepsilon$ decreases to $\sigma(a, b, m, \Delta)$ as $\varepsilon\downarrow0$.

We fix $\omega \in \Omega_T$, which is omitted from the notation, and we define the random times
\begin{equation*}
	\xi_n \vcentcolon= \inf \set{t \geq a + \sigma_0}{q_n(t, m \Delta) = 1}.
\end{equation*}
The proofs of \eqref{seq: main result 1} and \eqref{seq: main result 2} will be completed if we show that $\xi_n \leq a + \sigma$ for all large enough $n$. Indeed, if this claim is established, then \eqref{seq: main result 1} and \eqref{seq: main result 2} become a consequence of Lemma \ref{lem: lemma 2 for main result} with $j \vcentcolon= m\Delta$, $\zeta_{n, 1} \vcentcolon= \xi_n$ and $\zeta_{n, 2} \vcentcolon= b$. In order to see why, observe that $\ell_n(t) \leq m \Delta$ for all $t \in [a + \sigma_0, b]$ and all sufficiently large $n$ by Proposition \ref{prop: bounded threshold}, so the hypothesis of Lemma \ref{lem: lemma 2 for main result} holds.

Furthermore, by Propositions \ref{prop: relative compactness of occupancy state sample paths} and \ref{prop: bounded threshold}, this sequence may be chosen so that the next two properties hold.
\begin{enumerate}
	\item[(i)] $\set{q_k}{k \in \mathcal{K}}$ converges to some function $q \in D_{\mathbbm{R}^{\mathbbm{N}}}[0, T]$ with respect to $\varrho$.

	\item[(ii)] $\ell_k(t) \leq m \Delta$ for all $t \in [a + \sigma_0, b]$ and all $k \in \mathcal{K}$.
\end{enumerate}

Let $v(m \Delta + 1)$ be the function defined in the statement of Proposition \ref{prop: tail number of tasks}, as the uniform limit of the processes $v_k(m \Delta + 1)$ over the interval $[0, T]$. It follows from Propositions \ref{prop: total number of tasks} and \ref{prop: tail number of tasks} that
\begin{equation*}
	\sup_{t \in [0, T]} \left|u_k(t) - v_k(t, m\Delta + 1) - \left[u(t) - v(t, m \Delta + 1)\right]\right| \leq \varepsilon
\end{equation*}
for all sufficiently large $k \in \mathcal{K}$. For each of these $k \in \mathcal{K}$, we have
\begin{align*}
	\sum_{i = 1}^{m \Delta} q_k\left(a + \sigma_0 + \sigma(\varepsilon), i\right) &= u_k\left(a + \sigma_0 + \sigma(\varepsilon)\right) - v_k(a + \sigma_0 + \sigma(\varepsilon), m \Delta + 1) \\
	&\geq u\left(a + \sigma_0 + \sigma(\varepsilon)\right) - v(a + \sigma_0 + \sigma(\varepsilon), m \Delta + 1) - \varepsilon \\
	&> \rho_{\min} + \left[u(a + \sigma_0) - \rho_{\min}\right]\mathrm{e}^{-\mu\sigma(\varepsilon)} - u(a + \sigma_0)\mathrm{e}^{-\mu\sigma(\varepsilon)} - \varepsilon \\
	&= \rho_{\min} \left(1 - \mathrm{e}^{-\mu\sigma(\varepsilon)}\right) - \varepsilon = m \Delta.
\end{align*}
The third inequality follows from \eqref{eq: lower bound for u} and Proposition \ref{prop: tail number of tasks}, and the last equality follows from the definition of $\sigma(\varepsilon)$.

Fix an enumeration $\set{\nu_i}{i \geq 0}$ of $\mathbbm{N}^r$ and consider the metric $d$ defined by
\begin{equation*}
	d(x, y) \vcentcolon= \sum_{i = 0}^\infty \frac{\min \left\{|x(\nu_i) - y(\nu_i)|, 1\right\}}{2^i} \quad \text{for all} \quad x, y \in \mathbbm{R}^{\mathbbm{N}^r}.
\end{equation*}

The topology of uniform convergence equipped to $D_{\mathbbm{R}^{\mathbbm{N}^r}}[0, T]$ is generated by the following metric:
\begin{equation*}
	\varrho(x, y) \vcentcolon= \sup_{t \in [0, T]} d\left(x(t), y(t)\right) \quad \text{for all} \quad x, y \in D_{\mathbbm{R}^{\mathbbm{N}^r}}[0, T].
\end{equation*}

The sample paths of the occupancy states and thresholds are defined as deterministic functions of the following stochastic primitives.

\begin{itemize}
	\item \textit{Driving Poisson processes:} a family $\set{\mathcal{N}_{(\nu, i, j)}}{\nu \in \mathbbm{N}^r,\ i \in \{0, \dots, r\}\ \text{and}\ j \in \{0, 1\}}$ of unit-rate independent Poisson processes, defined on a common probability space $(\Omega_D, \mathcal{F}_D, \mathbbm{P}_D)$.

	\item \textit{Selection variables:} a sequence $\set{U_j}{j \geq 1}$ of independent and identically distributed uniform random variables with values on $[0, 1)$, defined on a common probability space $(\Omega_S, \mathcal{F}_S, \mathbbm{P}_S)$.

	\item \textit{Initial conditions:} a family $\set{s_n(0)}{n \geq 1}$ of random variables describing the initial conditions of the systems, defined on a common probability space $(\Omega_I, \mathcal{F}_I, \mathbbm{P}_I)$ and satisfying the assumptions introduced in Section \ref{sec: notation and assumptions}.
\end{itemize}

For each occupancy state $s \in S$, we define the intervals
\begin{equation*}
	I_i(s) \vcentcolon= \left[1 - \sum_{j = i}^\infty s\left(\nu_j\right), 1 - \sum_{j = i + 1}^\infty s\left(\nu_j\right)\right) \quad \text{for all} \quad i \geq 0.
\end{equation*}

If $q(j) < 1$, then we let
\begin{equation*}
	J_i(s, j) \vcentcolon= \left[\frac{1 - \sum_{k = i}^\infty s\left(\nu_k\right) \ind{\Sigma_k < j}}{1 - q(j)}, \frac{1 - \sum_{k = i + 1}^\infty s\left(\nu_k\right)\ind{\Sigma_k < j}}{1 - q(j)}\right) \quad \text{for all} \quad i \geq 0.
\end{equation*}
These intervals yield another partition of $[0, 1)$. In this case, the length of $J_i(s, j)$ is the fraction of server pools with occupancy profile $\nu_i$ but only among those server pools with at most $j - 1$ tasks in total; we adopt the convention that $J_i(s, j) \vcentcolon= \emptyset$ for all $i \geq 0$ when $q(j) = 1$.

We define
\begin{equation*}
	r_{ij}(s, \ell) \vcentcolon= \begin{cases}
		\ind{U_j \in J_i(s, \ell)} & \text{if} \quad \Sigma_i < \ell, \\
		\ind{q(\ell) = 1, U_j \in J_i(s, h)} & \text{if} \quad \ell \leq \Sigma_i < h, \\
		\ind{q(h) = 1, U_j \in I_i(s)} & \text{if} \quad \Sigma_i \geq h,
	\end{cases}
	\quad \text{for all} \quad i,j \geq 1.
\end{equation*}

In this section we establish a few asymptotic dynamical properties concerning the following four processes:
\begin{equation} u_n \vcentcolon= \sum_{i = 1}^\infty q_n(i), \quad x_n \vcentcolon= \sum_{i = 1}^{\floor{\rho}_\Delta} q_n(i), \quad y_n \vcentcolon= \sum_{i = \floor{\rho}_\Delta + 1}^{\floor{\rho}_\Delta + \Delta} q_n(i) \quad \text{and} \quad z_n \vcentcolon= \sum_{i = \floor{\rho}_\Delta + \Delta + 1}^\infty q_n(i).
\end{equation}

The tasks on each row may be arranged in an arbitrary manner, ignoring the phase in which they are, but regardless of how tasks are arranged within each row, every task may leave the system at a rate that is at least
\begin{equation*}
	\eta \vcentcolon= \min \set{(1 - p_m)\mu_m}{1 \leq m \leq r} > 0.
\end{equation*}

Assume that $x(t) < \floor{\rho}_\Delta$ for some $t \in (t_0, t_1)$ and write $\ell \vcentcolon= \floor{\rho}_\Delta$ for brevity. Since $x$ is continuous and $x_k$ converges uniformly to $x$, there exist $a < t < b$ such that
\begin{equation} x_k(\tau) < \ell = \ell_k(\tau) \quad \text{for all} \quad \tau \in [a, b] \subset (t_0, t_1) \quad \text{and all large enough} \quad k \in \mathcal{K}.
\end{equation}
Below we establish (i) by proving that
\begin{equation*}
	y(\tau) - y(a) \leq -\int_a^\tau \eta \left[y(\zeta) - \Delta z(\zeta)\right]d\zeta \quad \text{for all} \quad \tau \in [a, b].
\end{equation*}

Now observe that
\begin{align*}
	\sum_{\Sigma_i = \sigma} \bar{\mathcal{D}}_k(\nu_i) &= \sum_{\Sigma_i = \sigma} \sum_{m = 1}^r \left[\mathcal{D}_k(\nu_i + e_m, m) - \mathcal{D}_m(\nu_i, m)\right] \\
	&= \sum_{\Sigma_i = \sigma + 1} \sum_{m = 1}^r \mathcal{D}_k(\nu_i, m) - \sum_{\Sigma_i = \sigma} \sum_{m = 1}^r \mathcal{D}_k(\nu_i, m).
\end{align*}
As a result, we may write
\begin{subequations}
	\begin{align}
		&y_k(\tau) - y_k(a) = \sum_{j = \ell + 1}^{\ell + \Delta} \sum_{\sigma = j}^\infty \left[D_k(\sigma + 1) - D_k(\sigma)\right] = - \sum_{j = \ell + 1}^{\ell + \Delta} D_k(j), \\
		&D_k(\sigma) \vcentcolon= \sum_{\Sigma_i = \sigma} \sum_{m = 1}^r \left[\mathcal{D}_k(\tau, \nu_i, m) - \mathcal{D}_k(a, \nu_i, m)\right].
	\end{align}
\end{subequations}
Here the last identity in \eqref{seq: expression for yk} uses \eqref{eq: boundedness of occupancy states and thresholds coxian case}, which implies that $D_k(\sigma) = 0$ if $\sigma > B_T$.

Using \eqref{seq: fslln for departures 2 coxian case}, we conclude that
\begin{equation*}
	\lim_{k \to \infty} D_k(j) = \sum_{\Sigma_i = j} \sum_{m = 1}^r \int_a^\tau (1 - p_m)\mu_m\nu_i(m)s(\zeta, \nu_i)d\zeta \geq \int_a^\tau \sum_{\Sigma_i = j} \eta j s(\zeta, \nu_i)d\zeta.
\end{equation*}
Therefore, taking limits on both sides of \eqref{seq: expression for yk}, we obtain
\begin{equation*}
	y(\tau) - y(a) \leq - \int_a^\tau \sum_{j = \ell + 1}^{\ell + \Delta} \sum_{\Sigma_i = j} \eta j s(\zeta, \nu_i)d\zeta \leq - \int_a^\tau \eta \left[y(\zeta) - \Delta z(\zeta)\right] d\zeta.
\end{equation*}
For the last inequality, note that
\begin{align*}
	\sum_{j = \ell + 1}^{\ell + \Delta} \sum_{\Sigma_i = j} js_k(\nu_i) &= \sum_{j = \ell + 1}^{\ell + \Delta} j\left[q_k(j) - q_k(j + 1)\right] \\
	&= y_k + \ell q_k(\ell + 1) - (\ell + \Delta) q_k(\ell + \Delta + 1) \\
	&\geq y_k - \Delta q_k(\ell + \Delta + 1) \geq y_k - \Delta z_k.
\end{align*}
Clearly, the inequality between the extremes also holds if $s_k$, $y_k$ and $z_k$ are replaced by their limits $s$, $y$ and $z$. This completes the proof (i).

Let $\ell \vcentcolon= \floor{\rho}_\Delta$ for brevity, and choose $\varepsilon > 0$ such that $\ell + 3\varepsilon < \rho < \ell + \Delta$. It follows from \eqref{eq: general total number of tasks} that $u$ is differentiable. Furthermore, $u(t) \to \rho$ and $\dot{u}(t) \to 0$ as $t \to \infty$. Therefore, there exists a time $t_0 \geq 0$ such that
\begin{equation} \ell + 3\varepsilon < u(t) < \ell + \Delta \quad \text{and} \quad \dot{u}(t) > -\eta\varepsilon \quad \text{for all} \quad t \in [t_0, T].
\end{equation}

Fix an increasing sequence of natural numbers. By Proposition \ref{prop: relative compactness of occupancy state sample paths coxian case}, there exists a subsequence $\mathcal{K}$ such that $\set{s_k}{k \in \mathcal{K}}$ converges to a function $s \in D_{\mathbbm{R}^{\mathbbm{N}^r}}[0, T]$ with respect to $\varrho$. Also, it follows from Proposition \ref{prop: mass processes coxian case} that $\set{x_k}{k \in \mathcal{K}}$, $\set{y_k}{k \in \mathcal{K}}$ and $\set{z_k}{k \in \mathcal{K}}$ converge uniformly over $[0, T]$ to absolutely continuous functions $x$, $y$ and $z$, respectively. Moreover,
\begin{equation} z(t) \leq z(t_0)\mathrm{e}^{-\eta(t - t_0)} \leq u(t_0)\mathrm{e}^{-\eta(t - t_0)} \quad \text{for all} \quad t \in [t_0, T]
\end{equation}
by property (ii) of Proposition \ref{prop: mass processes coxian case}. In particular,
\begin{equation*}
	z(t) < \frac{\varepsilon}{\Delta + 1} \quad \text{for all} \quad t \in [t_1, T], \quad \text{where} \quad t_1 \vcentcolon= t_0 + \frac{1}{\eta}\left[\log\left(\frac{(\Delta + 1)u(t_0)}{\varepsilon}\right)\right]^+.
\end{equation*}

Suppose that $x(t) < \ell$ for some $t \in (t_1, T)$, then the next statements hold almost everywhere on a neighborhood of $t$. Since $y = u - x - z > u - \ell - z$, Proposition \ref{prop: mass processes coxian case} and \eqref{eq: conditions on u} imply that
\begin{equation*}
	\dot{y} \leq -\eta \left(y - \Delta z\right) < -\eta \left[u - \ell - (\Delta + 1)z\right] < -2\eta\varepsilon.
\end{equation*}
As a result, we have $\dot{x} = \dot{u} - \dot{y} - \dot{z} \geq \dot{u} - \dot{y} > \eta\varepsilon$, where the last inequality uses \eqref{eq: conditions on u}. Thus,
\begin{equation} x(t) = \ell \quad \text{for all} \quad t \in [\sigma, T] \quad \text{with} \quad \sigma \vcentcolon= t_1 + \frac{\ell}{\eta\varepsilon}.
\end{equation}
Here $\sigma$ is an upper bound for the time until $x$ reaches $\ell$ if $x(t_1) < \ell$, computed from $\dot{x} > \eta\varepsilon$. Also, $x$ cannot decrease once it reaches $\ell$ since $\dot{x} > \eta\varepsilon$ almost everywhere on $\set{t \in (t_1, T)}{x(t) < \ell}$.

Let $D[0, T]$ denote the space of real c\`adl\`ag functions on $[0, T]$, endowed with the uniform norm:
	\begin{equation*}
		\norm{x}_T = \sup_{t \in [0, T]} |x(t)| \quad \text{for all} \quad x \in D[0, T].
	\end{equation*}

We only need to prove the converse, so assume that the sequences $\set{x_n(i)}{n \geq 1}$ are relatively compact for all $i \geq 0$. Given an increasing sequence $\mathcal{K} \subset \mathbbm{N}$, we must show that there exists a subsequence of $\set{x_k}{k \in \mathcal{K}}$ which converges with respect to $\varrho$. For this purpose, we may construct a family of increasing sequences $\set{\mathcal{J}_i}{i \geq 0}$ with the following properties.
	\begin{enumerate}
		\item[(i)] $\mathcal{J}_{i + 1} \subset \mathcal{J}_i \subset \mathcal{K}$ for all $i \geq 0$.

		\item[(ii)] $\set{x_j(i)}{j \in \mathcal{J}_i}$ has a limit $x(i) \in D[0, T]$ for each $i \geq 0$.
	\end{enumerate}

Consider the sequence $\set{k_j}{j \geq 1} \subset \mathcal{K}$ such that $k_j$ is the $j^{\text{th}}$ element of $\mathcal{J}_j$. Then
	\begin{equation*}
		\lim_{j \to \infty} \norm{x_{k_j}(i) - x(i)}_T = 0 \quad \text{for all} \quad i \geq 0.
	\end{equation*} 
	Define $x \in D_{\mathbbm{R}^{\mathbbm{N}}}[0, T]$ so that its coordinates are the functions $x(i)$ introduced in~(ii). Then $x_{k_j}$ converges to $x$ with respect to $\varrho$, which completes the proof.

Consider the sets
	\begin{equation*}
		L_M \vcentcolon= \set{x \in D[0, T]}{x(0) = 0\ \text{and}\ |x(t) - x(s)| \leq M|t - s|\ \text{for all}\ s, t \in [0, T]},
	\end{equation*}
	which are compact by the Arzel\'a-Ascoli theorem.

For this purpose, we introduce the spaces
	\begin{equation*}
		L_M^\varepsilon \vcentcolon= \set{x \in D[0, T]}{x(0) = 0\ \text{and}\ |x(t) - x(s)| \leq M|t - s| + \varepsilon\ \text{for all}\ s, t \in [0, T]}.
	\end{equation*}

Let us fix $i \geq 1$, the statement holds trivially if $i = 0$. Recall that $\lambda$ is a bounded function, thus there exists $K > 0$ such that $|\lambda(t)| \leq K$ for all $t \in [0, T]$. We have
	\begin{align*}
		\left|\mathcal{A}_n(t, i) - \mathcal{A}_n(s, i)\right| &\leq \frac{1}{n} \left|\mathcal{N}_n^\lambda(t) - \mathcal{N}_n^\lambda(s)\right| \\
		&\leq \left|\int_s^t \lambda(u)du\right| + 2\sup_{r \in [0, T]} \left|\frac{1}{n}\mathcal{N}_n^\lambda(r) - \int_0^r \lambda(v)dv\right| \\
		&\leq K|t - s| + 2\sup_{r \in [0, T]} \left|\frac{1}{n}\mathcal{N}_n^\lambda(r) - \int_0^r \lambda(v)dv\right| \quad \text{for all} \quad s, t \in [0, T].
	\end{align*}
	By Proposition \ref{prop: definition of Gamma_T}, there exists a vanishing sequence $\set{\delta_{i, n}^1 > 0}{n \geq 1}$ such that
	\begin{align*}
		\left|\mathcal{A}_n(t, i) - \mathcal{A}_n(s, i)\right| \leq K|t - s| + \delta_{i, n}^1 \quad \text{for all} \quad s, t \in [0, T].
	\end{align*}

For each $t \in [0, T]$, let us define
	\begin{align*}
		f_n(t, i) = \int_0^t \mu i\left[q_n(s, i) - q_n(s, i + 1)\right]ds,
	\end{align*}
	which is a non-decreasing function. Also, $f_n(0, i) = 0$ and $|f_n(t, i) - f_n(s, i)| \leq \mu i|t - s|$ for all $s, t \in [0, T]$. In particular, $f_n(T, i) \leq \mu i T$. Using these properties, we conclude that
	\begin{align*}
		\left|\mathcal{D}_n(t, i) - \mathcal{D}_n(s, i)\right| &\leq \frac{1}{n} \left|\mathcal{N}_i\left(n f_n(t, i)\right) - \mathcal{N}_i\left(n f_n(s, i)\right)\right| \\
		&\leq |f_n(t, i) - f_n(s, i)| + 2\sup_{r \in [0, T]} \left|\frac{1}{n}\mathcal{N}_i\left(n f_n(r, i)\right) - f_n(r, i)\right| \\
		&\leq \mu i|t - s| + 2\sup_{r \in [0, \mu iT]} \left|\frac{1}{n}\mathcal{N}_i(n r) - r\right| \quad \text{for all} \quad s, t \in [0, T].
	\end{align*}
	It follows from \eqref{seq: fslln for departures} that there exists a vanishing sequence $\set{\delta_{i, n}^2 > 0}{n \geq 1}$ such that
	\begin{align*}
		\left|\mathcal{D}_n(t, i) - \mathcal{D}_n(s, i)\right| \leq \mu i|t - s| + \delta_{i, n}^2 \quad \text{for all} \quad s, t \in [0, T].
	\end{align*}
	The proof is completed setting $M_i \vcentcolon= \max\{K, \mu i\}$ and $\varepsilon_{i, n} \vcentcolon= \max\{\delta_{i, n}^1, \delta_{i, n}^2\}$.

As above, we fix an arbitrary $\omega \in \Gamma_T$ and we omit it from the notation for brevity. It follows from \eqref{seq: occupancy state} and \eqref{seq: convergence of initial conditions} that it is enough to establish the result for the sequences $\set{\mathcal{A}_n}{n \geq 1}$ and $\set{\mathcal{D}_n}{n \geq 1}$. For this it suffices to show that $\set{\mathcal{A}_n(i)}{n \geq 1}$ and $\set{\mathcal{D}_n(i)}{n \geq 1}$ are relatively compact subsets of $D[0, T]$ for all $i \geq 0$, such that the limits of their convergent subsequences are Lipschitz; the sufficiency was explained above. We fix $i \geq 0$ and we do this just for $\set{\mathcal{A}_n(i)}{n \geq 1}$ since the same arguments can be used if $\mathcal{A}_n$ is replaced by $\mathcal{D}_n$. Let $M_i$ and $\set{\varepsilon_{i, n}}{n \geq 1}$ be as in the statement of Lemma ef{lem: approximate lipschitz property}. It follows from Lemma ef{lem: lemma from bramson} that for each $n$ there exists $x_n(i) \in L_{M_i}$ such that $
orm{\mathcal{A}_n(i) - x_n(i)}_T \leq 4\varepsilon_{i, n}$. Recall that $L_{M_i}$ is compact, thus every increasing sequence of natural numbers has a subsequence $\mathcal{K}$ such that $\set{x_k(i)}{k \in \mathcal{K}}$ converges to some function $x \in L_{M_i}$. Also, note that  egin{equation*} \limsup_{k 	o \infty} 
orm{\mathcal{A}_k(i) - x(i)}_T \leq \lim_{k 	o \infty} 
orm{\mathcal{A}_k(i) - x_k(i)}_T + \lim_{k 	o \infty} 
orm{x_k(i) - x(i)}_T = 0; \end{equation*} the limits are taken along $\mathcal{K}$. This proves that every subsequence of $\set{\mathcal{A}_n(i)}{n \geq 1}$ has a further subsequence which converges to a Lipschitz function.

Let $M_i$ and $\set{\varepsilon_{i, n}}{n \geq 1}$ be as in the statement of Lemma \ref{lem: approximate lipschitz property}. It follows from Lemma \ref{lem: lemma from bramson} that for each $n$ there exists $x_n(i) \in L_{M_i}$ such that $\norm{\mathcal{A}_n(i) - x_n(i)}_T \leq 4\varepsilon_{i, n}$. Recall that $L_{M_i}$ is compact, thus every increasing sequence of natural numbers has a subsequence $\mathcal{K}$ such that $\set{x_k(i)}{k \in \mathcal{K}}$ converges to some function $x \in L_{M_i}$. Also, note that
	\begin{equation*}
		\limsup_{k \to \infty} \norm{\mathcal{A}_k(i) - x(i)}_T \leq \lim_{k \to \infty} \norm{\mathcal{A}_k(i) - x_k(i)}_T + \lim_{k \to \infty} \norm{x_k(i) - x(i)}_T = 0;
	\end{equation*}
	the limits are taken along $\mathcal{K}$. This proves that every subsequence of $\set{\mathcal{A}_n(i)}{n \geq 1}$ has a further subsequence which converges to a Lipschitz function.

It is enough to establish that
	\begin{equation*}
		\bigcap_{m \geq 1} \bigcup_{n \geq m} \set{\omega \in \Omega}{\sup_{t \in [0, T]} n^\gamma\left|\frac{\mathcal{N}(\omega, n t)}{n} - t\right| \geq \varepsilon}
	\end{equation*}
	has probability zero for each $\gamma \in [0, 1/2)$ and each $\varepsilon > 0$. Let us fix $\gamma$ and $\varepsilon$, by the Borel-Cantelli lemma, it suffices to prove that
	\begin{equation*}
		\sum_{n = 1}^\infty \mathbbm{P}\left(\sup_{t \in [0, T]} \left|\mathcal{N}(n t) - nt\right| \geq \varepsilon n^{1 - \gamma}\right) < \infty \quad \text{for all} \quad \varepsilon > 0.
	\end{equation*}

For each $k \geq 1$, the process $\left[\mathcal{N}(t) - t\right]^{2k}$ is a submartingale. It follows from Doob's inequality that
	\begin{equation*}
		\mathbbm{P}\left(\sup_{t \in [0, T]} \left|\mathcal{N}(n t) - nt\right| \geq \varepsilon n^{1 - \gamma}\right) \leq \frac{\mu_{2k}(n T)}{\varepsilon^{2k}n^{2k(1 - \gamma)}},
	\end{equation*}
	where $\mu_i(x)$ denotes the $i^{\text{th}}$ central moment of the Poisson distribution with mean $x$. Below we prove that there exists $k$ such that the sum over $n$ of the expression on the right-hand side is finite.

The central moments $\mu_i(x)$ are polynomials of $x$ such that
	\begin{equation*}
		\mu_1(x) = 0, \quad \mu_2(x) = x \quad \text{and} \quad \mu_{i + 1}(x) = x\left[\mu_i'(x) + i\mu_{i - 1}(x)\right] \quad \text{for all} \quad i \geq 2;
	\end{equation*}
	for the last identity see \cite[Equation (5.22)]{kendall1945advanced}. This recursion implies that $\mu_{2i}$ and $\mu_{2i + 1}$ have degree~$i$. Therefore, there exist coefficients $a_{k, j}$ such that
	\begin{equation*}
		\mu_{2k}(n T) = \sum_{j = 0}^k a_{k, j} n^j.
	\end{equation*}

Fix $k$ such that $k - 2k \gamma > 1$ and observe that
	\begin{equation*}
		\frac{\mu_{2k}(n T)}{\varepsilon^{2k}n^{2k(1 - \gamma)}} = \sum_{j = 0}^k \frac{a_{k, j}}{\varepsilon^{2k}} \left(\frac{1}{n}\right)^{2k - j - 2k\gamma}.
	\end{equation*}
	To conclude, note that $2k - j - 2k\gamma \geq k - 2k\gamma > 1$ for all $0 \leq j \leq k$. Hence,
	\begin{align*}
		\sum_{n = 1}^\infty \frac{\mu_{2k}(n T)}{\varepsilon^{2k}n^{2k(1 - \gamma)}} \leq \sum_{n = 1}^\infty \left(\sum_{j = 0}^k \frac{a_{k, j}}{\varepsilon^{2k}}\right) \left(\frac{1}{n}\right)^{k - 2k\gamma} < \infty.
	\end{align*}
	This completes the proof.

We fix an arbitrary $\omega \in \Omega_T$, which is omitted from the notation for brevity. It follows from Proposition \ref{prop: definition of Omega_T} that $q_n(i)$, $\mathcal{A}_n(i)$ and $\mathcal{D}_n(i)$ are identically zero for all large enough $n$ and all $i > B_T' \vcentcolon= B_T + \Delta$\footnote{If $B_T' = B_T$, a task can be sent to a server pool with $B_T$ tasks and at the same instant a task can leave from the same server pool, although this has probability zero; here $q_n(B_T + 1)$ remains zero but $\mathcal{A}_n(B_T + 1)$ and $\mathcal{D}_n(B_T + 1)$ have a jump. Setting $B_T' = B_T + \Delta$ precludes arrivals to server pools with $B_T'$ tasks since $\ell_n \leq B_T$.}. Consequently, we have
	\begin{align*}
		u_n(t) = \sum_{i = 1}^{B_T'} q_n(t, i) &= u_n(0) + \sum_{i = 1}^{B_T'} \left[\mathcal{A}_n(t, i) - \mathcal{D}_n(t, i)\right] \\
		&= u_n(0) + \frac{1}{n}\mathcal{N}_n^\lambda(t) - \sum_{i = 1}^{B_T'} \mathcal{D}_n(t, i)
	\end{align*}
	for all $t \in [0, T]$ and all large enough $n$.

To prove the proposition, it suffices to establish that every increasing sequence of natural numbers has a subsequence $\mathcal{K}$ such that $\set{u_k}{k \in \mathcal{K}}$ converges uniformly over $[0, T]$ to $u$. For this purpose, we first observe that \eqref{seq: convergence of initial conditions 2} and \eqref{seq: fslln for arrivals 2} imply that
	\begin{equation*}
		\lim_{n \to \infty} u_n(0) = u(0) \quad \text{and} \quad \lim_{n \to \infty} \sup_{t \in [0, T]} \left|\frac{1}{n}\mathcal{N}_n^\lambda(t) - \int_0^t \lambda(s)ds\right| = 0.
	\end{equation*}

Given an increasing sequence of natural numbers, Proposition \ref{prop: relative compactness of occupancy state sample paths} implies that there exist some subsequence $\mathcal{K}$ and a function $q \in D_{\mathbbm{R}^{\mathbbm{N}}}[0, T]$, such that $\set{q_k}{k \in \mathcal{K}}$ converges to $q$ with respect to $\varrho$; note that $q(i)$ is identically zero for all $i > B_T'$. If we define $\tilde{u} \vcentcolon= \sum_{i = 1}^{B_T'} q(i)$, then $\set{u_k}{k \in \mathcal{K}}$ converges to $\tilde{u}$ uniformly over $[0, T]$, and \eqref{seq: fslln for departures 2} yields
	\begin{align*}
		&\lim_{k \to \infty} \sup_{t \in [0, T]} \left|\sum_{i = 1}^{B_T'} \mathcal{D}_k(t, i) - \int_0^t \mu \tilde{u}(s)ds\right| = \\
		&\lim_{k \to \infty} \sup_{t \in [0, T]} \left|\sum_{i = 1}^{B_T'} \left[\mathcal{D}_k(t, i) - \int_0^t \mu i \left[q(s, i) - q(s, i + 1)\right]ds\right]\right| = 0.
	\end{align*}
	We conclude that $\map{\tilde{u}}{[0, T]}{[0, \infty)}$ satisfies the integral equation
	\begin{equation*}
		\tilde{u}(t) = u(0) + \int_0^t \left[\lambda(s) - \mu\tilde{u}(s)\right]ds \quad \text{for all} \quad t \in [0, T].
	\end{equation*}

Therefore, it is enough to show that
	\begin{equation*}
		\bigcap_{m \geq 1} \bigcup_{n \geq m} \set{\omega \in \Omega}{u_n(\omega, t) \geq M\ \text{for some}\ t \in [0, T]}
	\end{equation*}
	has probability zero for some $M \in \mathbbm{N}$. Consider the sets
	\begin{equation*}
		E_n^M \vcentcolon= \set{\omega \in \Omega}{u_n(\omega, t) \geq M\ \text{for some}\ t \in [0, T]}.
	\end{equation*}
	By the Borel-Cantelli lemma, it suffices to prove that there exists $M \in \mathbbm{N}$ such that
	\begin{equation} \sum_{n = 1}^\infty \mathbbm{P}\left(E_n^M\right) < \infty.
	\end{equation}

The total number of tasks in the system at time $t$ is upper bounded by $\mathcal{N}_n^\lambda(t) + nu_n(0)$, the number of arrivals during $[0, t]$ plus the initial number of tasks in the system. Hence,
	\begin{align*}
		\mathbbm{P}\left(E_n^M\right) &\leq \mathbbm{P} \left(\mathcal{N}_n^\lambda(t) + nu_n(0) \geq nM \ \text{for some} \ t \in [0, T]\right) \\
		&\leq \mathbbm{P} \left(\mathcal{N}_n^\lambda(t) + n B \geq nM \ \text{for some} \ t \in [0, T]\right) = \mathbbm{P} \left(\mathcal{N}_n^\lambda(T) \geq n\left(M - B\right) \right).
	\end{align*}
	The second inequality follows from $q_n(0, B + 1) = 0$, which implies that $u_n(0) \leq B$.

Applying a Chernoff bound, we conclude that
	\begin{align*}
		\mathbbm{P}\left(E_n^M\right) \leq \mathbbm{P}\left(\mathcal{N}_n^\lambda(T) \geq n(M - B) \right) \leq \frac{\mathrm{e}^{\lambda T \left(\mathrm{e} - 1\right)n}}{\mathrm{e}^{(M - B)n}} = \mathrm{e}^{\left[\lambda T(\mathrm{e} - 1) + B - M\right]n}.
	\end{align*}
	Therefore, \eqref{eq: borel-cantelli condition coxian case} holds for any $M > \lambda T (\mathrm{e} - 1) + B$.

For all sufficiently large $n$, the $i^{\text{th}}$ term in each of the summations appearing in \eqref{seq: number of tasks in phase 1} and \eqref{seq: number of tasks in phase k} is zero if $\Sigma_i > B_T'$, a condition that is met by all but finitely many $i$. Therefore, as in the proof of Proposition \ref{prop: total number of tasks}, it follows from \eqref{seq: convergence of initial conditions 2 coxian case}, \eqref{seq: fslln for arrivals 2 coxian case} and \eqref{seq: fslln for departures 2 coxian case} that every increasing sequence of natural numbers has a subsequence $\mathcal{K}$ such that $\set{(u_k^1, \dots, u_k^r)}{k \in \mathcal{K}}$ converges uniformly over $[0, T]$ to a function $(u^1, \dots, u^r)$ that solves
	\begin{align*}
		&\dot{u}^1 = \lambda - \mu_1u^1, \\
		&\dot{u}^m = p_{m - 1}\mu_{m - 1}u^{m - 1} - \mu_m u^m \quad \text{if} \quad m \neq 1.
	\end{align*}
	This system of differential equations has a unique solution with initial conditions $u^m(0)$ defined as in the statement of the proposition. Since $u_n^m(0)$ converges to $u^m(0)$ for all $m$ by \eqref{seq: convergence of initial conditions 2 coxian case}, it follows that $\set{(u_n^1, \dots, u_n^r)}{n \geq 1}$ converges uniformly over $[0, T]$ to this unique solution.
